//! Quality snapshot for audio2midi, generated by sdsp-test-kit. The plugin is a pass-through for
//! audio (Thru 1): the probes pin that it stays transparent.
//!
//!     SDSP_UPDATE_SNAPSHOTS=1 cargo test -p superduper-audio2midi --test quality

use sdsp_test_kit::probes::{self, db};
use sdsp_test_kit::{render_effect, PluginUnderTest, Suite};

struct Target;
impl PluginUnderTest for Target {
    type Plugin = superduper_audio2midi::SuperDuperAudio2Midi;
    const ID: &'static std::ffi::CStr = c"co.superduperai.audio2midi";
}

const SR: f64 = 48_000.0;

#[test]
fn quality_snapshot() {
    let mut s = Suite::new("audio2midi", concat!(env!("CARGO_MANIFEST_DIR"), "/tests/quality.snap")).default_tolerance(0.2);
    let frames = 1 << 15;
    let tone = probes::tone(SR as f32, 1000.0, 0.5, frames);
    let (out, _) = render_effect::<Target>(SR, &tone, &tone);
    s.record("tone_gain_db", probes::gain_db(&tone, &out));
    s.record("tone_peak_db", db(probes::peak(&out)));
    s.record("tone_thd_db", probes::thd_at(&out, 1000.0, SR as f32));
    let noise = probes::noise(frames, 0.3);
    let (nout, _) = render_effect::<Target>(SR, &noise, &noise);
    s.record("noise_gain_db", probes::gain_db(&noise, &nout));
    s.record("noise_max_step", probes::max_step(&nout));
    sdsp_test_kit::params::record_table(&mut s, superduper_audio2midi::PARAMS);
    s.finish();
}

#[test]
fn parameter_table_is_consistent() {
    sdsp_test_kit::params::check_table("superduper-audio2midi", superduper_audio2midi::PARAMS, &[0, 1, 2, 3, 4, 5, 9]);
}
